/**
 * @method
 * @name img_study_onclick
 * @description 「study」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_study_onclick = async function() {
    try {
        // ATS 거래종목에 해당하는 경우 or 예약공시에 해당하는 경우 시간 체크
        if (scwin.gAtsIsuYn === 'Y' || scwin.gBatchReservYn === 'Y') {
            await scwin.getMktclsYn();
        } else {
            await scwin.dsclStudy(); // 검토

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10008.img_study_onclick" });
    }
};

