/**
 * @method
 * @name cmb_ATS_TRNSM_YN_OnSelChange
 * @description cmb_ATS_TRNSM_YN 선택 변경 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ATS_TRNSM_YN_OnSelChange = function() {
    try {
        if (cmb_ATS_TRNSM_YN.getValue() === '') {
            scwin.disableObj("study");
        } else {
            if (img_study.getDisabled()) {
                scwin.enableObj("study");
            }
            if (pnl_today.style.display !== "none") {
                // 당일배포 체크박스 패널 활성화 시
                if (cmb_ATS_TRNSM_YN.getValue() === 'Y') {
                    // ATS 전송여부가 전송일 때 당일배포 체크
                    chb_today.setValue(1);
                    chb_today.setDisabled(true);
                    rdo_trnsmtp.setValue('1');
                    rdo_trnsmtp.setDisabled(true);
                } else {
                    chb_today.setDisabled(false);
                    rdo_trnsmtp.setDisabled(false);
                }
                rdo_trnsmtp.focus();
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10008.cmb_ATS_TRNSM_YN_OnSelChange" });
    }
};

