    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getProcButtonYN
 * @description 로그인 사용자정보로 공시처리가능여부 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getProcButtonYN = async function() {
    const sbmOptions = {
        id : "sbm_dts_btnshow",
        action : "/Viewer.do",
        ref : "",
        target : "dts_btnshow=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name dsclStudy
 * @description 검토처리하기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dsclStudy = async function() {
    // 전송구분 셋팅
    const vTrnsmtp = rdo_trnsmtp.getValue();
    // alert(vTrnsmtp +"="+gAcptNo);
    if (scwin.gAcptNo === '') {
        await $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    dts_AcptProcs.insertRow();
    dts_AcptProcs.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_AcptProcs.setCellData(1, "TRNSM_TP_CD", vTrnsmtp);
    dts_AcptProcs.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_AcptProcs.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    if (scwin.gNxtTpCd === 2) {
        // 당일일때
        dts_AcptProcs.setCellData(1, "NXTDD_TDD_TP", "2");
        vMethod = "processDisclosureStudy";
    } else {
        // 전체가 체크일때
        if (chb_today.checked === true) {
            // 우편함 익익을 당일로
            dts_AcptProcs.setCellData(1, "NXTDD_TDD_TP", "3");
            vMethod = "processDisclosureStudyNxt";
        } else {
            // 우편함이므로 1로 셋팅
            dts_AcptProcs.setCellData(1, "NXTDD_TDD_TP", "1");
            vMethod = "processDisclosureStudy";
        }
    }
    if (dts_AcptProcs.getCellData(1, "ACPT_NO") === '') {
        await $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    const gShowloadYn = $c.frame.path("../frame_head").gShowloadYn;
    // alert('[gShowloadYn]'+gShowloadYn);

    if (gShowloadYn !== 'Y') {
        await $c.win.alert('문서 변환중이오니  변환완료후에 처리하시기 바랍니다.');
        return false;
    }
    if (cmb_ATS_TRNSM_YN.getValue() === 'Y') {
        // ATS 전송여부가 전송일 때 해당 컬럼 저장
        dts_AcptProcs.setCellData(1, "ATS_TRNSM_YN", cmb_ATS_TRNSM_YN.getValue());
    }

    // ATS 전송 체크
    if (await scwin.checkATS()) {
        let sMsg = "";
        if (scwin.gBatchReservYn === 'Y') {
            // 20시 이전 예약공시
            sMsg = '20시 이후에 배포됩니다.(예약공시)\n';
        } else if (scwin.gBatchReservYn === 'N') {
            // 20시 이후 예약공시
            sMsg = '즉시 배포됩니다.\n';
        }
        sMsg += '검토처리 하시겠습니까?';
        if (confirm(sMsg)) {
            if (await scwin.getProcsSate(scwin.gAcptNo) === false) {
                scwin.closeParentReload();
                return false;
            } else {
                trs_AcptProcs.KeyName = "toinb_dataid4";
                const sbmOptions = {
                    id : "sbm_trs_AcptProcs",
                    action : "/DisclosureStudy.do",
                    ref : "dts_AcptProcs",
                    target : "trs_AcptProcs=body.content",
                    isProcessMsg : false
                };

                const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
            }
        }
    }
};

