/**
 * @method
 * @name getProcsSate
 * @description 처리상태 조회하기
 * @param {*} gAcptNo gAcptNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getProcsSate = async function(gAcptNo) {
    const sbmOptions = {
        id : "sbm_dts_procs_stat",
        action : "/Viewer.do",
        ref : "",
        target : "dts_procs_stat=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const vPROCS_STAT_CD = dts_procs_stat.getCellData(1, "PROCS_STAT_CD");
    const vPROCS_STAT_NM = dts_procs_stat.getCellData(1, "PROCS_STAT_NM");
    const vPROCS_DDTM = dts_procs_stat.getCellData(1, "PROCS_DDTM");
    const vBLOCK_YN = dts_procs_stat.getCellData(1, "BLOCK_YN");
    if (vBLOCK_YN === 'Y') {
        await $c.win.alert(scwin.gTrdHaltMsg);
        return false;
    }
    if (scwin.gProcsStatCd !== vPROCS_STAT_CD) {
        await $c.win.alert("본 공시가 " + vPROCS_DDTM + "에  이미 [" + vPROCS_STAT_NM + "] 처리가 되었습니다.");
        // fn_CloseParentReload();
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name dsclHold
 * @description 거래소제출문서 즉시 보류처리하기
